import html, os, json
T=json.load(open('../data/trust.json'))
_M=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']
REV=f"{_M[int(T['reviewed'][5:7])-1]} de {T['reviewed'][:4]}"
CSS = """
:root{--ink:#0F1B33;--green:#35D07F;--red:#FF5247;--muted:#9FB0CC;--card:#16264A;--soft:#DCE5F5}
*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--soft);font:17px/1.55 'Hanken Grotesk',system-ui,sans-serif}
main{max-width:720px;margin:0 auto;padding:32px 20px 64px}
h1,h2{font-family:'Big Shoulders Display',sans-serif;font-weight:900;color:#fff;line-height:1.05;margin:0}
h1{font-size:clamp(40px,9vw,64px)}h1 em{font-style:normal;color:var(--green)}h2{font-size:32px;margin:36px 0 10px}
.top{color:var(--muted);font-weight:700;font-size:15px;margin-bottom:18px}.top a{color:var(--green);text-decoration:none}
p{margin:10px 0}.lead{font-size:19px;color:var(--soft)}
.card{background:var(--card);border-radius:18px;padding:18px 20px;margin:14px 0}
ul.chk{list-style:none;padding:0;margin:10px 0}ul.chk li{padding:9px 0 9px 36px;position:relative;border-bottom:1px solid rgba(159,176,204,.18)}
ul.chk li:before{content:"";position:absolute;left:4px;top:13px;width:18px;height:18px;border:2px solid var(--green);border-radius:5px}
dl{margin:0}dt{font-weight:700;color:#fff;margin-top:14px}dd{margin:2px 0 0;color:var(--soft)}
table{width:100%;border-collapse:collapse;margin:10px 0}th,td{text-align:left;padding:9px 8px;border-bottom:1px solid rgba(159,176,204,.25)}th{color:var(--green)}
.small{font-size:14px;color:var(--muted)}.btn{display:inline-block;margin:6px 8px 6px 0;padding:10px 16px;border-radius:12px;background:var(--green);color:var(--ink);font-weight:700;text-decoration:none}
a.g{display:block;text-decoration:none;color:inherit}a.g .card{transition:transform .15s}a.g:hover .card{transform:translateY(-2px)}
.kw{display:inline-block;background:var(--green);color:var(--ink);font-weight:800;border-radius:8px;padding:1px 8px;font-size:14px;margin-left:8px;vertical-align:middle}
@media print{body{background:#fff;color:#111}h1,h2,dt{color:#111}.card{background:#f3f5f9}.btn,.top a{display:none}ul.chk li{border-color:#ccc}}
"""
HEAD = """<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>%s · Tu Amigo de las Finanzas</title>
<link href="https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@800;900&family=Hanken+Grotesk:wght@400;500;700&display=swap" rel="stylesheet"><style>%s</style><script data-goatcounter="https://tuamigodelasfinanzas.goatcounter.com/count" async src="https://gc.zgo.at/count.js"></script></head><body><main>"""
FOOT = """<p class="small">Contenido informativo y educativo. No es asesoramiento financiero ni fiscal. Comprueba siempre los datos y plazos vigentes en las fuentes oficiales.</p>
<p class="small">Revisado en %s · <a href="metodologia.html" style="color:#35D07F">Cómo trabajamos</a> · <a href="./" style="color:#35D07F">Más guías</a> · @tuamigodelasfinanzas</p></main></body></html>""" % REV
def e(s): return html.escape(s)
def chk(items): return '<ul class="chk">'+''.join(f'<li>{e(i)}</li>' for i in items)+'</ul>'
def dl(items): return '<dl>'+''.join(f'<dt>{e(a)}</dt><dd>{e(b)}</dd>' for a,b in items)+'</dl>'
def table(h,rows): return '<table><tr>'+''.join(f'<th>{e(x)}</th>' for x in h)+'</tr>'+''.join('<tr>'+''.join(f'<td>{e(c)}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def card(x): return f'<div class="card">{x}</div>'
def sec(t,b): return f'<h2>{e(t)}</h2>{b}'
def page(slug,title,sub,body):
    h=HEAD%(e(title.replace('<em>','').replace('</em>','')),CSS)+f'<div class="top">@tuamigodelasfinanzas · <a href="./">Todas las guías</a> · <a href="javascript:window.print()">Imprimir o guardar en PDF</a></div><h1>{title}</h1><p class="lead">{e(sub)}</p>'+body+FOOT
    open(f'{slug}.html','w',encoding='utf-8').write(h)

page('ahorro','Presupuesto mensual <em>en 15 minutos</em>','Para saber a dónde se va tu dinero y decidir cuánto apartar, sin hojas de cálculo complicadas.',
 sec('Paso 1 · Apunta lo que entra',chk(['Sueldo neto del mes (lo que llega a tu cuenta)','Ingresos extra habituales (alquiler, pensiones, trabajos puntuales)','Pagas extra: si se prorratean, ya están dentro; si no, apúntalas en el mes en que llegan']))+
 sec('Paso 2 · Apunta lo que sale',table(['Tipo','Ejemplos','Cuánto al mes'],[['Fijos','Alquiler o hipoteca, luz, agua, internet, seguros','___ €'],['Variables necesarios','Compra, transporte, farmacia','___ €'],['Suscripciones','Streaming, apps, gimnasio','___ €'],['Ocio y caprichos','Restaurantes, ropa, viajes','___ €'],['Ahorro','Lo que apartas el día que cobras','___ €']]))+
 sec('Una referencia, no una regla: 50 / 30 / 20',card('<p>Mucha gente usa este reparto como punto de partida: <b>50 %</b> para necesidades, <b>30 %</b> para deseos y <b>20 %</b> para ahorro. Con un sueldo neto de 1.500 €, serían 750 €, 450 € y 300 €.</p><p class="small">Cada hogar es distinto. Si tus gastos fijos ya pasan del 50 %, ajusta los porcentajes a tu situación; lo importante es tener un reparto claro.</p>'))+
 sec('Paso 3 · Automatiza',chk(['Programa una transferencia a tu cuenta de ahorro el día que cobras','Separa el dinero del mes en dos cuentas: gastos y ahorro','Revisa el presupuesto el primer domingo de cada mes (10 minutos)','Si un mes te pasas, apúntalo y corrige el siguiente; no hace falta empezar de cero']))+
 sec('Tu colchón',card('<p>Una pauta habitual es reunir entre <b>3 y 6 meses</b> de gastos fijos para imprevistos. Empieza por un primer objetivo pequeño, por ejemplo un mes de gastos.</p>')))

page('renta','Checklist de la <em>declaración de la renta</em>','Lo que conviene tener a mano antes de abrir el borrador.',
 sec('Antes de empezar',chk(['Ten a mano tu DNI y el medio con el que te identificas en la Agencia Tributaria (Cl@ve, certificado digital)','Consulta en la web oficial las fechas de la campaña: suele ir de abril a finales de junio, pero cambia cada año','Revisa los datos fiscales que la Agencia ya tiene sobre ti (descárgalos desde su sede electrónica)']))+
 sec('Documentos habituales',chk(['Certificado de retenciones de tu empresa (si no aparece ya en tus datos fiscales)','Extractos o certificados de intereses de cuentas y depósitos','Información de fondos, acciones o criptomonedas vendidos durante el año','Recibos del alquiler (si eres inquilino) o datos de las propiedades que tengas','Justificantes de aportaciones a planes de pensiones','Datos de hijos y personas a tu cargo (fechas de nacimiento, convivencia)','Gastos con posible deducción estatal o autonómica (donativos, rehabilitación, etc.)']))+
 sec('Antes de enviarla',chk(['Revisa el borrador línea por línea; el borrador no es definitivo hasta que lo confirmas','Comprueba tu número de cuenta si te sale a pagar o a devolver','Guarda el justificante de presentación y un PDF de la declaración','Si tienes dudas con tu caso (varios pagadores, venta de inmuebles, extranjero), consulta con un asesor fiscal']))+
 sec('Glosario rápido',dl([('Base imponible','La parte de tus ingresos sobre la que se calcula el impuesto.'),('Retención','Lo que tu pagador ya adelanta a Hacienda en cada nómina.'),('Deducción','Una cantidad que reduce lo que pagas directamente.'),('Borrador','Propuesta de declaración que elabora la Agencia con tus datos.')])))

page('vivienda','Comprar o alquilar <em>con cabeza</em>','Una lista para comprobar antes de firmar una hipoteca o un contrato de alquiler.',
 sec('Si compras: el presupuesto',chk(['Calcula tu cuota máxima: una referencia habitual es el 30–35 % de tu sueldo neto','Reserva la entrada: lo normal es aportar alrededor del 20 % del precio','Suma los gastos de la compra: suelen rondar el 10–12 % del precio, según comunidad y tipo de vivienda','Deja un colchón para obras, mudanza y muebles']))+
 sec('Si compras: los documentos',chk(['Nota simple del Registro de la Propiedad: titular y cargas','Certificado energético','Recibos del IBI y de la comunidad al corriente','Estado del edificio: derramas, obras previstas, ITE','Visita la vivienda varias veces y a distintas horas']))+
 sec('La hipoteca',chk(['Pide la FEIN (ficha con todas las condiciones) de al menos tres bancos','Compara la TAE, no solo el tipo de interés','Calcula lo que cuestan las vinculaciones (seguros, nómina, tarjetas) y si compensan','Decide entre fija, variable o mixta según cuánto margen tengas en la cuota','Revisa la comisión de amortización anticipada de tu contrato']))+
 sec('Si alquilas',chk(['La fianza legal es de una mensualidad; la garantía adicional puede llegar a dos más como máximo','Lee la duración, las subidas permitidas y quién paga cada gasto','Haz fotos del estado de la vivienda el día de la entrada','Guarda los recibos de fianza y mensualidades','Comprueba si tu zona está declarada tensionada en la web de tu comunidad']))+
 sec('Señales de un alquiler falso',card('<p>Precio muy por debajo del mercado, un propietario que "está fuera", prisa por pagar una señal sin ver el piso y pagos por vías sin rastro. <b>No pagues nada sin visitar la vivienda y comprobar quién es el propietario.</b></p>')))

page('estafas','Guía <em>antiestafas</em>','Las trampas más comunes y qué hacer en los primeros minutos si caes.',
 sec('Las estafas más comunes',table(['Estafa','Cómo la reconoces'],[['SMS falso del banco','Urgencia, enlace extraño y te piden claves'],['Paquete retenido','Una pequeña tasa a pagar por un enlace'],['"Mamá, soy yo"','Un número nuevo que pide dinero con prisa'],['Bizum "por error"','Te piden devolver dinero que no has recibido'],['Falsa llamada del banco','Te piden mover tu dinero o un código'],['Inversión milagro','Rentabilidad enorme y garantizada, con famosos'],['Falsa Hacienda','Una devolución a cambio de tus datos de tarjeta'],['Segunda mano','Un enlace de cobro fuera de la plataforma'],['Falso soporte técnico','Te piden instalar un programa de control remoto'],['Estafa romántica','Una persona que no puedes ver te pide dinero'],['Oferta de empleo falsa','Mucho dinero por reenviar pagos de otros']]))+
 sec('Reglas de oro',chk(['Tu banco nunca te pide claves ni que muevas tu dinero','Si hay prisa, es una señal de alarma','No pulses enlaces de mensajes: entra tú desde la app o la web oficial','Ante la duda, llama tú al número oficial y no al del mensaje','Nada de dinero a desconocidos por vías sin rastro','Activa la verificación en dos pasos en tus cuentas']))+
 sec('Si ya has caído: los primeros minutos',chk(['Llama a tu banco y bloquea tarjetas y accesos','Guarda capturas, mensajes y recibos','Cambia las contraseñas desde otro dispositivo','Denuncia en la Policía Nacional o la Guardia Civil','Consulta con la Línea de Ayuda en Ciberseguridad del INCIBE, el 017 (gratuita y confidencial)']))+
 sec('No te avergüences',card('<p>Cualquiera puede caer: los estafadores son profesionales y cuentan con tu prisa. Contarlo ayuda a que otros no caigan.</p>')))

terms=[('Acción','Parte del capital de una empresa.'),('Bolsa','Mercado donde se compran y venden acciones y otros valores.'),('Índice','Cesta de valores que mide la evolución de un mercado (IBEX 35, S&P 500).'),('IBEX 35','Índice de las 35 mayores empresas de la bolsa española.'),('S&P 500','Índice de 500 grandes empresas de EE. UU.'),('Dividendo','Parte del beneficio que una empresa reparte a sus accionistas.'),('ETF','Fondo que cotiza en bolsa y suele replicar un índice.'),('Fondo de inversión','Vehículo que reúne el dinero de muchos inversores y lo gestiona.'),('Fondo indexado','Fondo que intenta replicar un índice.'),('Cartera','Conjunto de inversiones que tiene una persona.'),('Diversificar','Repartir el dinero entre distintos activos para no depender de uno.'),('Rentabilidad','Ganancia o pérdida de una inversión, normalmente en porcentaje.'),('Riesgo','Posibilidad de que el resultado sea distinto del esperado, incluida la pérdida.'),('Volatilidad','Cuánto sube y baja el precio de un activo.'),('Inflación','Subida general de precios; resta poder de compra al dinero.'),('Tipo de interés','Precio del dinero; lo fija el banco central y afecta a hipotecas y ahorro.'),('BCE','Banco Central Europeo, fija los tipos en la zona euro.'),('Fed','Banco central de EE. UU.'),('Bono','Deuda que emite un Estado o empresa y paga intereses.'),('Renta fija','Inversiones que pagan intereses acordados, como los bonos.'),('Renta variable','Inversiones cuyo resultado depende del mercado, como las acciones.'),('Mercado alcista','Periodo de subidas prolongadas.'),('Mercado bajista','Periodo de caídas prolongadas.'),('Capitalización','Valor total de una empresa en bolsa: precio por número de acciones.'),('PER','Precio de la acción entre el beneficio por acción.'),('Comisión','Coste por comprar, vender o mantener una inversión.'),('Broker','Intermediario a través del que compras y vendes valores.'),('Liquidez','Facilidad para convertir algo en dinero sin perder valor.'),('Interés compuesto','Intereses que generan nuevos intereses con el tiempo.'),('Horizonte temporal','Tiempo durante el que piensas mantener una inversión.')]
page('bolsa','Glosario de bolsa: <em>30 términos</em>','Para entender las noticias sin perderte con la jerga.',
 sec('De la A a la Z (más o menos)',dl(terms))+sec('Cómo usarlo',card('<p>Léelo una vez, y vuelve a él cuando una noticia use una palabra que no tengas clara. Si quieres más, cada semana publicamos una explicación en @tuamigodelasfinanzas.</p>')))

page('gastos','Revisión de <em>gastos fijos</em> y comisiones','Una tarde al año para detectar pagos que ya no necesitas.',
 sec('Suscripciones y servicios',chk(['Lista todas las suscripciones: streaming, música, apps, gimnasio, revistas','Marca las que no has usado en el último mes','Revisa si tienes servicios duplicados (dos plataformas de vídeo, dos seguros de móvil)','Pon en el calendario la fecha de renovación anual de las que mantienes']))+
 sec('Banco',chk(['Revisa las comisiones de mantenimiento, tarjetas y transferencias de tus cuentas','Comprueba si cumples las condiciones que eliminan las comisiones','Compara la TAE de tus cuentas y depósitos, no solo el TIN','Cancela tarjetas y cuentas que no usas']))+
 sec('Hogar y seguros',chk(['Compara tarifas de luz, gas, internet y móvil cada año','Revisa las coberturas de tus seguros y su precio al renovar','Mira si pagas por servicios añadidos que no necesitas']))+
 sec('TAE y TIN',card('<p>El <b>TIN</b> es el tipo de interés nominal, sin contar comisiones. La <b>TAE</b> incluye comisiones y la frecuencia de pago de intereses, y por eso sirve mejor para comparar productos.</p>'))+
 sec('Tu resumen',table(['Qué reviso','Cuánto pago al año','¿Lo mantengo?'],[['','___ €',''],['','___ €',''],['','___ €','']])))

page('tramites','Guía de <em>trámites y ayudas</em>','Qué gestión hacer, dónde y con qué antes de empezar. Todo en las webs oficiales y casi siempre gratis.',
 sec('Antes de cualquier trámite',chk(['Ten a mano tu DNI o NIE en vigor','Consigue una forma de identificarte en internet: Cl@ve o certificado digital','Entra siempre desde la web oficial del organismo, no desde un anuncio ni un enlace de un mensaje','Desconfía de quien cobre por pedir una cita o por gestionar una ayuda: la mayoría de citas y consultas son gratuitas']))+
 sec('Dónde se hace cada cosa',table(['Gestión','Organismo','Qué suele pedir'],[['Vida laboral, pensión, ingreso mínimo vital, prestación por nacimiento','Seguridad Social','Cl@ve o certificado digital'],['Prestación por desempleo (paro)','SEPE','Cl@ve, certificado de empresa y cita o solicitud online'],['Declaración de la renta, datos fiscales, certificados','Agencia Tributaria','Cl@ve o certificado digital'],['Certificado de empadronamiento','Ayuntamiento','DNI y, en muchos casos, solicitud online'],['Ayudas al alquiler y a la vivienda','Tu comunidad autónoma','Contrato, ingresos y requisitos de cada convocatoria'],['Becas de estudios','Ministerio de Educación y tu comunidad','Solicitud en plazo y datos de renta'],['Reclamación a un banco','Banco de España','Respuesta previa del banco o plazo agotado'],['Reclamación de consumo','OMIC o consumo de tu comunidad','Hoja de reclamaciones y justificantes']]))+
 sec('Si piensas pedir una ayuda',chk(['Busca la convocatoria en la web oficial y lee requisitos, importe y plazo','Comprueba tus ingresos y tu situación familiar con los datos que pide la ayuda','Reúne los documentos antes de abrir la solicitud','Guarda el justificante de presentación y el número de expediente','Revisa la sede electrónica de vez en cuando: pueden pedirte documentos adicionales']))+
 sec('Cada cuánto conviene revisar',card('<p>Las ayudas, los importes y los plazos cambian con frecuencia. Usa esta guía como mapa y confirma siempre las cifras y fechas en la web oficial del organismo antes de decidir.</p>')))

page('metodologia','Cómo <em>trabajamos</em>','Qué hacemos, de dónde salen los datos y cómo corregimos los errores.',
 sec('Qué es esta cuenta',card('<p>@tuamigodelasfinanzas explica el dinero sin jerga: ahorro, vivienda, estafas, Renta y bolsa. Es contenido <b>educativo</b>. No somos asesores financieros ni fiscales, y no recomendamos productos, entidades ni operaciones concretas.</p>'))+
 sec('De dónde salen los datos',table(['Tema','Fuentes'],[['Precio de la luz','Red Eléctrica (PVPC)'],['Euríbor y euro-dólar','Banco Central Europeo'],['IPC e inflación','INE'],['Carburantes','Ministerio para la Transición Ecológica'],['Bolsa, índices, oro y petróleo','Datos públicos de mercado (Polygon, Yahoo Finance, Alpha Vantage)'],['Criptomonedas','CoinGecko'],['Calendario de bancos centrales, IPC y empleo de EE. UU., festivos','Federal Reserve, BCE, BLS, NYSE, Bolsas y Mercados Españoles'],['Ahorro, vivienda y banca','Banco de España, CNMV, Ministerio de Vivienda, BOE'],['Impuestos y Renta','Agencia Tributaria y BOE'],['Estafas','INCIBE (línea 017), Policía Nacional']]))+
 sec('Qué verás en cada publicación',dl([('Fuentes','La última diapositiva de cada carrusel indica de dónde sale la información. Si el dato es concreto (una cifra, una fecha), se cita la fuente exacta en el pie de la publicación.'),('Fecha de revisión','El contenido educativo lleva el mes en que se revisó por última vez.'),('Ejemplos','Usan números redondos y se presentan siempre como ejemplo. No son predicciones ni casos reales.'),('Referencias','Reglas como el reparto 50/30/20 son puntos de partida, no normas. Cada hogar es distinto.')]))+
 sec('Cómo lo revisamos',chk(['Los datos fiscales y legales tienen fecha de caducidad y se comprueban en la fuente oficial antes de cada campaña o cambio de año','Si un dato caduca sin revisar, ese contenido no se publica','Cada seis meses se repasa todo el contenido educativo','Los datos de mercado se descargan automáticamente de fuentes públicas el mismo día; pueden tener retraso respecto al cierre']))+
 sec('Qué hay detrás',card('<p>Parte de la producción (datos, gráficos y publicación) está automatizada para que los datos salgan puntuales y sin errores de copia. Los textos educativos se elaboran a partir de fuentes oficiales.</p><p class="small">A fecha de hoy no tenemos acuerdos con bancos, brokers ni plataformas. Si algún día hay contenido patrocinado, lo indicaremos de forma clara en la propia publicación.</p>'))+
 sec('Privacidad',card('<p>Estas guías miden las visitas con <b>GoatCounter</b>, una herramienta que no usa cookies, no crea perfiles ni guarda datos personales: solo cuenta cuántas veces se abre cada página, para saber qué guías os resultan útiles.</p>'))+
 sec('Correcciones',card('<p>Si ves un error, escríbenos por mensaje directo a <b>@tuamigodelasfinanzas</b> o coméntalo en la publicación. Lo comprobamos con la fuente oficial, lo corregimos y lo anotamos aquí.</p>')+'<h2 style="font-size:24px;margin-top:22px">Registro de correcciones</h2><p class="small">Sin correcciones hasta ahora (actualizado en '+REV+').</p>')+
 sec('Aviso legal',card('<p>Todo el contenido es informativo y educativo. No constituye asesoramiento financiero, fiscal ni legal personalizado, ni una recomendación de compra o venta de ningún producto. Invertir en bolsa conlleva riesgo, incluida la pérdida de parte o de todo el dinero invertido, y las rentabilidades pasadas no garantizan las futuras. Antes de tomar decisiones importantes, consulta con un profesional autorizado y comprueba los datos y plazos vigentes en las fuentes oficiales.</p>')))

idx=HEAD%('Guías gratis',CSS)+'<div class="top">@tuamigodelasfinanzas</div><h1>Guías <em>gratis</em></h1><p class="lead">Plantillas y listas para ahorrar mejor y entender tu dinero. Todo gratis, sin registro.</p>'
for slug,k,t,d in [('ahorro','AHORRO','Presupuesto mensual en 15 minutos','Plantilla paso a paso y reparto 50/30/20 como referencia.'),('renta','RENTA','Checklist de la declaración de la renta','Documentos y pasos antes de abrir el borrador.'),('bolsa','BOLSA','Glosario de bolsa: 30 términos','Para entender las noticias sin jerga.'),('gastos','GASTOS','Revisión de gastos fijos y comisiones','Suscripciones, banco, seguros, TAE y TIN.'),('vivienda','VIVIENDA','Comprar o alquilar con cabeza','Presupuesto, documentos, hipoteca y contrato de alquiler.'),('estafas','ESTAFAS','Guía antiestafas','Las trampas más comunes y qué hacer si caes.'),('tramites','TRAMITES','Guía de trámites y ayudas','Qué gestión hacer, dónde y con qué antes de empezar.')]:
    idx+=f'<a class="g" href="{slug}.html"><div class="card"><h2 style="margin:0 0 4px;font-size:28px">{t}<span class="kw">{k}</span></h2><p style="margin:0">{d}</p></div></a>'
idx+='<a class="g" href="metodologia.html"><div class="card"><h2 style="margin:0 0 4px;font-size:28px">Cómo trabajamos</h2><p style="margin:0">De dónde salen los datos, cómo se revisan y cómo corregimos errores.</p></div></a>'
idx+=FOOT
open('index.html','w',encoding='utf-8').write(idx)
print('ok')
